comp.body:
query myQuery($orderBy: [ExpenseRuleOrderBy!], $limit: Int, $offset: Int) {
  ExpenseRule(orderBy: $orderBy, limit: $limit, offset: $offset, where: {code: {_isNull: false}, isDeleted: {_eq: false}}) {
    id
    version
    code
    calculationTypeRef
    standard
    activeFrom
    activeTo
    name

    currencyRef
    deductionLimit
    taxesCode
    useLastCountry
    nonpayableCode
    advancePaymentCode
    countryRef
    useSingleCurrency
  }
  ExpenseRuleFlag {
      expenseRuleId
      value
      name
  }
  ExpenseRuleAggregate {
    aggregate {
      count
    }
  }
}

