let elements = filters?.ExpensesFinalList?.ExpenseRule;
if (!Array.isArray(elements)) {
  return [];
}

const returnedArray = elements?.map(element => ({
  id: element.id,
  code: element?.code || "",
  name: element?.name || "",
  calculationTypeRef: element?.calculationType,
  activeFrom: element?.activeFrom,
  activeTo: element?.activeTo,
  standard: element?.standard,
  currency: element?.currency?.code ? element.currency.code : '', 
  deductionLimit: element?.deductionLimit,
  taxesCode: element?.taxesCode,
  useLastCountry: element?.useLastCountry,
  nonpayableCode: element?.nonpayableCode,
  advancePaymentCode: element?.advancePaymentCode,
  countryRef: element?.countryRef,
  useSingleCurrency: element?.useSingleCurrency,
  version: element?.version,
  updatedAt: element.createdAt
}));

return returnedArray.length > 0 ? returnedArray : [];

comp.body:
query countExpenseRuleOccurence($expenseRuleId: uuid!) {
  numberOfRequestPositions: ExpenseRequestAggregate(where: {_or: [{expenseItem: {expensePosition: {expenseRuleGeneralExpenseId: {_eq: $expenseRuleId}}}}, {expenseItem: {expensePosition: {expenseRuleAllowanceCodeId: {_eq: $expenseRuleId}}}}, {expenseItem: {expensePosition: {expenseRuleMileageId: {_eq: $expenseRuleId}}}}]}) {
    aggregate {
      count
    }
  }
  numberOfRulesAssigned: ExpenseRuleAssignmentAggregate(where: {expenseRule: {id: {_eq: $expenseRuleId}}}) {
    aggregate {
      count
    }
  }
  numberOfPlanItems: ExpensePlanAggregate(where: {_or: [{expensePlanItem: {expenseRuleGeneralExpenseId: {_eq: $expenseRuleId}}}, {expensePlanItem: {expenseRuleAllowanceCodeId: {_eq: $expenseRuleId}}}, {expensePlanItem: {expenseRuleMileageId: {_eq: $expenseRuleId}}}]}) {
    aggregate {
      count
    }
  }
}

transformers.script:
function transformString(input) {
  const parts = input.split(':');
  const transformed = parts[2]
    .split('_')
    .map(word => word.charAt(0).toUpperCase() + word.slice(1))
    .join(' ');

  return transformed;
}

return transformString

const orderByConditions = expenseTable.sortColumns.map(({ column, desc }) => {
  const order = desc ? "DESC_NULLS_LAST" : "ASC_NULLS_LAST";

  const columnMappings = {
    code: {code: order},
    name: { name: order},
    calculationTypeRef:  {calculationTypeRef: order},
    activeFrom: {activeFrom: order},
    activeTo:  {activeTo :  order},
    standard:  {standard: order},
    currencyRef: {currency:{code: order}},
  };

  return columnMappings[column] || {employee:{firstName: order, lastName:order}};
});

return orderByConditions

